package com.crm.invoice.service;import com.crm.invoice.entity.Invoice;import java.math.BigDecimal;
public final class InvoiceLifecycle {private InvoiceLifecycle(){}public static boolean reminders(Invoice r,BigDecimal paid){return !r.isArchived()&&java.util.Set.of("PENDING","UNPAID","PARTIALLY_PAID").contains(r.getStatus())&&r.getDueDate()!=null&&paid!=null&&paid.signum()>=0&&r.getTotalAmount().subtract(paid).signum()>0;}public static void archive(Invoice r,BigDecimal paid){if(r.isArchived())return;if(!("PAID".equals(r.getStatus())&&paid!=null&&paid.compareTo(r.getTotalAmount())==0)||r.getTotalAmount().signum()<=0)throw InvoiceWorkAccess.conflict();r.setArchived(true);}}
